// MinimockCreatePVZInspect logs each unmet expectation
func (m *PVZMock) MinimockCreatePVZInspect() {
	for _, e := range m.CreatePVZMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PVZMock.CreatePVZ at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterCreatePVZCounter := mm_atomic.LoadUint64(&m.afterCreatePVZCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.CreatePVZMock.defaultExpectation != nil && afterCreatePVZCounter < 1 {
		if m.CreatePVZMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PVZMock.CreatePVZ at\n%s", m.CreatePVZMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PVZMock.CreatePVZ at\n%s with params: %#v", m.CreatePVZMock.defaultExpectation.expectationOrigins.origin, *m.CreatePVZMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcCreatePVZ != nil && afterCreatePVZCounter < 1 {
		m.t.Errorf("Expected call to PVZMock.CreatePVZ at\n%s", m.funcCreatePVZOrigin)
	}

	if !m.CreatePVZMock.invocationsDone() && afterCreatePVZCounter > 0 {
		m.t.Errorf("Expected %d calls to PVZMock.CreatePVZ at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.CreatePVZMock.expectedInvocations), m.CreatePVZMock.expectedInvocationsOrigin, afterCreatePVZCounter)
	}
}

