// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *PVZMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCloseLastReceptionInspect()

			m.MinimockCreatePVZInspect()

			m.MinimockCreateProductInspect()

			m.MinimockCreateReceptionInspect()

			m.MinimockDeleteLastProductInspect()

			m.MinimockListPVZInspect()

			m.MinimockListPVZPaginatedInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *PVZMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *PVZMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCloseLastReceptionDone() &&
		m.MinimockCreatePVZDone() &&
		m.MinimockCreateProductDone() &&
		m.MinimockCreateReceptionDone() &&
		m.MinimockDeleteLastProductDone() &&
		m.MinimockListPVZDone() &&
		m.MinimockListPVZPaginatedDone()
}
